INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-periodico-viviente', 'El Periódico Viviente', 'Dinámica de dramatización periodística y lectura crítica donde los scouts representan un noticiero en vivo sobre noticias de campamento.', '<h2>📜 Descripción de El Periódico Viviente</h2>
<p><b>El Periódico Viviente</b> es una dinámica de expresión escénica periodística, análisis crítico de la actualidad e improvisación dramática. Organizados por patrullas, los scouts reciben recortes de titulares reales o inventan noticias sobre la vida del campamento (ej. <i>''El misterioso caso de las estacas perdidas''</i>, <i>''Nuevas construcciones en la cocina de patrulla''</i> o <i>''El pronóstico del clima para la gran excursión''</i>). Cada equipo debe transformar su sección de noticias en un noticiero de televisión o transmisión de radio dramatizada en vivo.</p>
<p>Los participantes asumen roles de presentadores de noticias, reporteros de campo en directo, entrevistados y corresponsales de deportes. Utilizando vestuario improvisado con hojas de periódico y micrófonos de papel, representan los hechos con humor, juicio crítico y sentido de la mística scout.</p>
<p>Esta actividad ejercita la soltura comunicativa, el pensamiento crítico, la improvisación en equipo y la conciencia social en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Periódico Viviente?</h2>
<p>Para llevar a cabo la dinámica con entusiasmo, agilidad y dinamismo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Redacción y Asignación de Noticias:</b> Cada patrulla selecciona un tema de actualidad del campamento o de la comunidad para convertirlo en noticia.</li>
  <li><b>Construcción de Escenografía y Utilería:</b> Usando papel de periódico y tijeras, los scouts confeccionan corbatas, sombreros de reportero y micrófonos de papel.</li>
  <li><b>Distribución de Funciones Periodísticas:</b> Se designan los roles: dos conductores de estudio, un reportero en vivo y dos personajes entrevistados.</li>
  <li><b>Presentación del Noticiero en Vivo:</b> Cada patrulla presenta su emisión de noticiero de 3 a 5 minutos ante la unidad completa.</li>
  <li><b>Cierre con Titular de la Jornada:</b> Al finalizar, se reflexiona comunitariamente sobre la veracidad de la información y la importancia de informarse responsablemente.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Periódico Viviente</h2>
<p>La actividad valora la agudeza crítica, el humor y la creatividad técnica en el Tally:</p>
<ul>
  <li><b>Mayor Ingenio y Humor Periodístico:</b> Otorgar 5 puntos a la patrulla que presente el noticiero más ágil, entretenido y articulado.</li>
  <li><b>Pensamiento Crítico y Mensaje:</b> Otorgar 3 puntos al equipo cuyo reporte transmita una enseñanza o valor scout de forma clara.</li>
  <li><b>Creatividad en Utilería de Papel:</b> Otorgar 3 puntos al grupo que elabore los mejores vestuarios y micrófonos con papel de periódico.</li>
</ul>', '/uploads/el-periodico-viviente.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Papel de Periódico", "Tijeras"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular el pensamiento crítico", "Estimular la creatividad", "Trabajo en equipo"], "justificacion_areas": "El Periódico Viviente potencia la creatividad al requerir la conversión inmediata de hechos escritos a representaciones dramáticas llenas de humor y carácter visual. Desarrolla la sociabilidad al fomentar el análisis crítico de la información, el trabajo colaborativo en patrulla y el respeto por las opiniones ajenas desde Manada hasta Clan.", "variaciones": "<b>Noticiero de Época Histórica:</b> Representar un noticiero ambientado en el campamento Brownsea de 1907.<br><b>Radio Noticiero a Ciegas:</b> Transmitir el noticiero sólo con efectos de sonido detrás de un biombo.<br><b>Periódico Mural Ilustrado:</b> Dibujar la portada del diario en papel kraft gigante.", "recomendaciones": "Promover que las noticias sobre el campamento sean siempre respetuosas y en tono festivo. Cuidar el uso de tijeras.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando en la actuación y dramatización del noticiero de Manada."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando los turnos de habla y actuación de la seisena."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando ideas y emociones a través de la representación periodística."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Colaborando alegremente en la elaboración de utilería con papel."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando la actuación de reportajes y entrevistas en vivo."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo la escucha limpia y la veracidad de la información."}, {"id": "8bbd7392-24e1-453f-bd7a-8265d57877c9", "area": "Creatividad", "unidad": "Compañía", "texto": "Saco mis propias conclusiones de los hechos que pasan a mi alrededor.", "como_se_cumple": "Analizando con pensamiento crítico los eventos del noticiero."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo la comunicación honesta y respetuosa en el equipo."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Aportando creatividad en la producción del noticiero de Tropa."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando trabajo en equipo y juego limpio en la transmisión."}, {"id": "fda4f3c9-2c6e-425d-9b86-3b37b40ddb8b", "area": "Creatividad", "unidad": "Tropa", "texto": "Saco mis propias conclusiones de los hechos que pasan a mi alrededor.", "como_se_cumple": "Evaluando críticamente las noticias y mensajes transmitidos."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y fraternidad en la patrulla."}, {"id": "fefc6ed0-97f8-4a71-99d9-f56729ba0a92", "area": "Creatividad", "unidad": "Avanzada", "texto": "Me informo de lo que pasa a mi alrededor y soy capaz de valorar críticamente lo que veo, leo y escucho.", "como_se_cumple": "Valorando críticamente la información y los medios de comunicación en Avanzada."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Promoviendo el ejercicio de una ciudadanía informada y responsable."}, {"id": "93cf0a2b-1fe0-45e2-b3d2-89828f64a016", "area": "Creatividad", "unidad": "Clan", "texto": "Me formo una opinión personal a partir de los libros que leo y de los documentos e informaciones que conozco por distintos medios.", "como_se_cumple": "Formándose una opinión personal fundamentada sobre la actualidad social en el Clan."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo el compromiso de la verdad y el servicio informado en la sociedad."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

